import numpy as np

def feature(size, free, rack, duration, temps, cooling, neighbors, server_free, running, queue, time):
    """Negative total size of queued jobs that would no longer fit on the candidate server after placing this job, normalised by 16*max(1,len(q))."""
    q = np.asarray(queue, dtype=float)
    if q.shape[0] == 0:
        return np.zeros(free.shape[0])
    qs = q[:, 0]
    fa = free - size          # free slots after placement
    fb = free                 # free slots before placement
    blocked = (qs[None, :] > fa[:, None]) & (qs[None, :] <= fb[:, None])
    w = (qs[None, :] * blocked).sum(axis=1)
    return -w / (16.0 * max(1, q.shape[0]))

import numpy as np

def feature(size, free, rack, duration, temps, cooling, neighbors, server_free, running, queue, time):
    """Negative post-placement rack load fraction scaled by the rack's self-susceptibility (diag of inverse coupling matrix), normalised by the max susceptibility."""
    R = temps.shape[0]
    cap = server_free.shape[1] * 16.0
    used = cap - server_free.sum(axis=1)
    M = np.diag(cooling + neighbors.sum(axis=1)) - neighbors + 1e-3 * np.eye(R)
    try:
        d = np.diag(np.linalg.inv(M))
    except np.linalg.LinAlgError:
        d = np.diag(np.linalg.pinv(M))
    dmax = d.max()
    if not np.isfinite(dmax) or dmax <= 1e-9:
        return np.zeros(rack.shape[0])
    r = rack.astype(int)
    load = (used[r] + size) / cap
    return -(load * (d[r] / dmax))

import numpy as np

def feature(size, free, rack, duration, temps, cooling, neighbors, server_free, running, queue, time):
    """Gated fit: if the largest queued job needs >=12 slots prefer the emptiest candidate (free/16), else prefer the snug one (-(free-size)/16)."""
    free = np.asarray(free, dtype=float)
    q = np.asarray(queue, dtype=float)
    qmax = float(np.max(q[:, 0])) if q.shape[0] > 0 else 16.0
    if qmax >= 12.0:
        v = free / 16.0
    else:
        v = -(free - float(size)) / 16.0
    return np.clip(v, -1.0, 1.0)

import numpy as np

def feature(size, free, rack, duration, temps, cooling, neighbors, server_free, running, queue, time):
    """Largest queued (else running) job size that still fits in the candidate server's leftover after placing, /16."""
    k = free.shape[0]
    if queue.shape[0] > 0:
        S = queue[:, 0]
    elif running.shape[0] > 0:
        S = running[:, 1]
    else:
        return np.zeros(k)
    L = free - size  # leftover per candidate
    # best_i = max over s in S of (s if s <= L_i else 0)
    fits = S[None, :] <= L[:, None]  # (k, |S|)
    vals = np.where(fits, S[None, :], 0.0)
    best = vals.max(axis=1)
    return best / 16.0

import numpy as np

def feature(size, free, rack, duration, temps, cooling, neighbors, server_free, running, queue, time):
    """Signed net conductive heat flow into each candidate rack from its neighbours, standardised across candidates."""
    k = rack.shape[0]
    if k <= 1:
        return np.zeros(k)
    # neighbors: (R, R); temps[rack]: (k,); temps[None, :]: (1, R)
    # flow into rack r = sum_a neighbors[r, a] * (temps[a] - temps[r])
    d = (neighbors[rack] * (temps[None, :] - temps[rack][:, None])).sum(axis=1)
    dmin = d.min()
    dmax = d.max()
    v = (d - d.mean()) / (dmax - dmin + 1e-3)
    return np.clip(v, -1.0, 1.0)

import numpy as np

def feature(size, free, rack, duration, temps, cooling, neighbors, server_free, running, queue, time):
    """Relative change in the number of servers per candidate rack that can still host the largest queued job, scaled by that job's size fraction."""
    k = free.shape[0]
    if queue.shape[0] == 0:
        return np.zeros(k)
    big = float(np.max(queue[:, 0]))
    if big <= 0:
        return np.zeros(k)
    S = server_free.shape[1]
    fit_r = (server_free >= big).sum(axis=1).astype(float)  # servers per rack that can host the largest waiter
    r = rack.astype(int)
    f = free.astype(float)
    after = fit_r[r] - (f >= big).astype(float) + ((f - size) >= big).astype(float)
    mean_after = float(np.mean(after))
    return (big / 16.0) * (after - mean_after) / max(S, 1)

import numpy as np

def feature(size, free, rack, duration, temps, cooling, neighbors, server_free, running, queue, time):
    """Fraction of queued slot-minutes (jobs whose size fits the candidate's leftover slots) this server can still shelter, mean-centred over candidates and scaled to [-1,1]."""
    k = free.shape[0]
    if queue.shape[0] == 0:
        return np.zeros(k)
    qs = queue[:, 0]
    w = queue[:, 0] * queue[:, 1]
    left = free - size
    fit = ((qs[None, :] <= left[:, None]) * w[None, :]).sum(axis=1) / max(w.sum(), 1e-9)
    centred = fit - fit.mean()
    return centred / (np.max(np.abs(centred)) + 1e-9)
